#!/usr/bin/env python3
import sys
import json
import os


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <directory>", file=sys.stderr)
        sys.exit(1)

    source_dir = os.path.realpath(sys.argv[1])

    if not os.path.isdir(source_dir):
        print(f"Not a directory: {source_dir}", file=sys.stderr)
        sys.exit(1)

    values = []
    for entry in sorted(os.listdir(source_dir)):
        full_path = os.path.join(source_dir, entry)
        if not entry.endswith(".json"):
            continue
        if not os.path.isfile(full_path):
            continue

        try:
            with open(full_path, "r") as f:
                data = json.load(f)
        except json.JSONDecodeError as exc:
            print(f"Skipping {full_path}: invalid JSON ({exc})", file=sys.stderr)
            continue
        except OSError as exc:
            print(f"Skipping {full_path}: read error ({exc})", file=sys.stderr)
            continue

        if isinstance(data, dict) and "cost_usd" in data:
            cost = data["cost_usd"]
            if isinstance(cost, (int, float)) and not isinstance(cost, bool):
                values.append(cost)
            else:
                print(
                    f"Skipping {full_path}: cost_usd is not numeric ({cost!r})",
                    file=sys.stderr,
                )

    total = sum(values)
    mean = total / len(values) if values else 0

    summary = {
        "source_dir": source_dir,
        "total": total,
        "mean": mean,
    }

    with open("summary.json", "w") as f:
        json.dump(summary, f, indent=2)


if __name__ == "__main__":
    main()
